INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('beavermoney/beavermoney/relay-pagination', 'community', 'beavermoney', 'beavermoney', 'beavermoney/beavermoney', 'relay-pagination', 0, 0, 52, '2026-03-02T01:56:10.923Z', '2026-03-02T02:26:24.580Z', 'f24f1da675d6af8b9e047207a0edd95df99bc2216e2e792ff1888876fc4f81f9', '{"id":"beavermoney/beavermoney/relay-pagination","name":"relay-pagination","description":{"zh":"Relay 分页 AI 代理帮助您记录交易并构建稳定的系统","ja":"リレー ページネーション AI エージェントは、取引を記録し堅牢なシステムを構築するのに役立ちます","ko":"릴레이 페이지네이션 AI 에이전트는 거래를 기록하고 안정적인 시스템을 구축하는 데 도움이 됩니다","es":"relay-pagination es una herramienta de AI que permite a los desarrolladores registrar transacciones y construir su propio dam, simplificando el proceso de desarrollo","fr":"relay-pagination est un outil d''IA qui permet aux développeurs d''enregistrer des transactions et de construire leur propre barrage, simplifiant le processus de développement","de":"relay-pagination ist ein AI-Tool, das es Entwicklern ermöglicht, Transaktionen aufzuzeichnen und ihren eigenen Damm zu bauen, wodurch der Entwicklungsprozess vereinfacht wird","pt":"O relay-pagination é uma ferramenta de IA que ajuda a logs de transações e construir sistemas mais eficientes","ru":"ИИ Агент relay-pagination - это инструмент, который помогает вести журналы транзакций и строить более эффективные системы","ar":"relay-pagination هو أداة ذكاء اصطناعي تساعد في تسجيل المعاملات وبناء أنظمة أكثر كفاءة","en":"Log your transactions. Build your dam."},"seo":{"title":{"zh":"AI智能代理 - Relay 分页","ja":"AIエージェント - リレー ページネーション","ko":"AI 에이전트 - 릴레이 페이지네이션","es":"Herramientas de AI: relay-pagination para desarrolladores","fr":"Outils d''IA : relay-pagination pour les développeurs","de":"AI-Tools: relay-pagination für Entwickler","pt":"Ferramentas de IA: relay-pagination","ru":"ИИ Агенты: relay-pagination","ar":"أدوات الذكاء الاصطناعي: relay-pagination","en":"relay-pagination"},"description":{"zh":"Relay 分页 AI 代理帮助您记录交易并构建稳定的系统","ja":"リレー ページネーション AI エージェントは、取引を記録し堅牢なシステムを構築するのに役立ちます","ko":"릴레이 페이지네이션 AI 에이전트는 거래를 기록하고 안정적인 시스템을 구축하는 데 도움이 됩니다","es":"relay-pagination es una herramienta de AI que permite a los desarrolladores registrar transacciones y construir su propio dam, simplificando el proceso de de...","fr":"relay-pagination est un outil d''IA qui permet aux développeurs d''enregistrer des transactions et de construire leur propre barrage, simplifiant le processus ...","de":"relay-pagination ist ein AI-Tool, das es Entwicklern ermöglicht, Transaktionen aufzuzeichnen und ihren eigenen Damm zu bauen, wodurch der Entwicklungsprozess...","pt":"O relay-pagination é uma ferramenta de IA que ajuda a logs de transações e construir sistemas mais eficientes","ru":"ИИ Агент relay-pagination - это инструмент, который помогает вести журналы транзакций и строить более эффективные системы","ar":"relay-pagination هو أداة ذكاء اصطناعي تساعد في تسجيل المعاملات وبناء أنظمة أكثر كفاءة","en":"Log your transactions. Build your dam."},"definition":{"en":"Log your transactions. Build your dam."},"features":{"zh":["记录交易","构建稳定的系统","支持多种开发语言","易于集成","高性能的页面分页"],"ja":["取引を記録","堅牢なシステムを構築","複数の開発言語をサポート","容易に統合","高性能のページ分割"],"ko":["거래를 기록","안정적인 시스템을 구축","다양한 개발 언어 지원"," 쉽게 통합","고성능 페이지 분할"],"es":["Registro de transacciones","Construcción de estructuras de datos","Integración con herramientas de desarrollo","Compatibilidad con múltiples plataformas","Seguridad y escalabilidad"],"fr":["Enregistrement de transactions","Construction de structures de données","Intégration avec des outils de développement","Compatibilité avec plusieurs plateformes","Sécurité et évolutivité"],"de":["Transaktionsaufzeichnung","Datenstrukturaufbau","Integration mit Entwicklungstools","Kompatibilität mit mehreren Plattformen","Sicherheit und Skalierbarkeit"],"pt":["Logs de transações eficientes","Construção de sistemas mais eficientes","Integração com React, Python e Node.js","CLI para facilitar a utilização","Agent para automação de tarefas"],"ru":["Эффективное ведение журналов транзакций","Строительство более эффективных систем","Интеграция с React, Python и Node.js","CLI для облегчения использования","Агент для автоматизации задач"],"ar":["تسجيل معاملات فعال","بناء أنظمة أكثر كفاءة","التكامل مع React و Python و Node.js","CLI لتسهيل الاستخدام","وكيل لتحسين الأداء"]},"keywords":{"zh":["AI智能代理","Relay 分页","记录交易","构建系统","开发工具","如何使用 Relay 分页","Relay 分页 教程","Relay 分页 alternative"],"ja":["AIエージェント","リレー ページネーション","取引を記録","システムを構築","開発ツール","リレー ページネーションの使い方","リレー ページネーション ガイド","リレー ページネーション alternative"],"ko":["AI 에이전트","릴레이 페이지네이션","거래를 기록","시스템을 구축","개발 도구","릴레이 페이지네이션 사용법","릴레이 페이지네이션 가이드","릴레이 페이지네이션 alternative"],"es":["cómo usar relay-pagination","qué es relay-pagination","relay-pagination alternativa","relay-pagination vs otras herramientas","instalación de relay-pagination","guía de configuración de relay-pagination","desarrollo de aplicaciones con relay-pagination"],"fr":["comment utiliser relay-pagination","qu''est-ce que relay-pagination","alternative à relay-pagination","relay-pagination vs d''autres outils","installation de relay-pagination","guide de configuration de relay-pagination","développement d''applications avec relay-pagination"],"de":["wie man relay-pagination verwendet","was ist relay-pagination","alternative zu relay-pagination","relay-pagination vs andere Tools","Installation von relay-pagination","Konfigurationsanleitung für relay-pagination","Entwicklung von Anwendungen mit relay-pagination"],"pt":["como usar relay-pagination","o que é relay-pagination","ferramentas de IA para logs de transações","alternativas para relay-pagination","relay-pagination vs outros agentes","instalar relay-pagination","guia de configuração do relay-pagination"],"ru":["как использовать relay-pagination","что такое relay-pagination","ИИ Агенты для ведения журналов транзакций","альтернативы для relay-pagination","relay-pagination vs другие агенты","установить relay-pagination","руководство по настройке relay-pagination"],"ar":["كيفية استخدام relay-pagination","ما هو relay-pagination","أدوات الذكاء الاصطناعي لتسجيل المعاملات","بديل ل relay-pagination","relay-pagination مقابل أدوات أخرى","تثبيت relay-pagination","دليل إعداد relay-pagination"]}},"owner":"beavermoney","repo":"beavermoney","repoPath":"beavermoney/beavermoney","stars":0,"forks":0,"updatedAt":"2026-03-02T01:56:10.923Z","topics":[],"category":"community","skillMd":{"name":"relay-pagination","description":"Use when relay pagination with cursor-based pagination, infinite scroll, load more patterns, and connection protocols.","bodyPreview":"# Relay Pagination\n\nMaster Relay''s cursor-based pagination for efficiently loading and displaying\nlarge datasets with infinite scroll and load more patterns.\n\n## Overview\n\nRelay implements the GraphQL Cursor Connections Specification for efficient\npagination. It provides hooks like usePaginationFragment for declarative\npagination with automatic cache updates and connection management.\n\n## Installation and Setup\n\n### Pagination Query Structure\n\n```graphql\n# schema.graphql\ntype Query {\n  posts(","body":"# Relay Pagination\n\nMaster Relay''s cursor-based pagination for efficiently loading and displaying\nlarge datasets with infinite scroll and load more patterns.\n\n## Overview\n\nRelay implements the GraphQL Cursor Connections Specification for efficient\npagination. It provides hooks like usePaginationFragment for declarative\npagination with automatic cache updates and connection management.\n\n## Installation and Setup\n\n### Pagination Query Structure\n\n```graphql\n# schema.graphql\ntype Query {\n  posts(\n    first: Int\n    after: String\n    last: Int\n    before: String\n  ): PostConnection!\n}\n\ntype PostConnection {\n  edges: [PostEdge!]!\n  pageInfo: PageInfo!\n  totalCount: Int\n}\n\ntype PostEdge {\n  cursor: String!\n  node: Post!\n}\n\ntype PageInfo {\n  hasNextPage: Boolean!\n  hasPreviousPage: Boolean!\n  startCursor: String\n  endCursor: String\n}\n\ntype Post {\n  id: ID!\n  title: String!\n  body: String!\n}\n```\n\n## Core Patterns\n\n### 1. Basic Pagination\n\n```javascript\n// PostsList.jsx\nimport { graphql, usePaginationFragment } from ''react-relay'';\n\nconst PostsListFragment = graphql`\n  fragment PostsList_query on Query\n  @refetchable(queryName: \"PostsListPaginationQuery\")\n  @argumentDefinitions(\n    first: { type: \"Int\", defaultValue: 10 }\n    after: { type: \"String\" }\n  ) {\n    posts(first: $first, after: $after)\n    @connection(key: \"PostsList_posts\") {\n      edges {\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n      pageInfo {\n        hasNextPage\n        endCursor\n      }\n    }\n  }\n`;\n\nfunction PostsList({ query }) {\n  const {\n    data,\n    loadNext,\n    loadPrevious,\n    hasNext,\n    hasPrevious,\n    isLoadingNext,\n    isLoadingPrevious,\n    refetch\n  } = usePaginationFragment(PostsListFragment, query);\n\n  return (\n    <div>\n      <button\n        onClick={() => refetch({ first: 10 })}\n        disabled={isLoadingNext}\n      >\n        Refresh\n      </button>\n\n      {data.posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n\n      {hasNext && (\n        <button\n          onClick={() => loadNext(10)}\n          disabled={isLoadingNext}\n        >\n          {isLoadingNext ? ''Loading...'' : ''Load More''}\n        </button>\n      )}\n    </div>\n  );\n}\n\nexport default PostsList;\n```\n\n### 2. Infinite Scroll\n\n```javascript\n// InfiniteScrollPosts.jsx\nimport { useEffect, useRef } from ''react'';\nimport { graphql, usePaginationFragment } from ''react-relay'';\n\nconst InfiniteScrollFragment = graphql`\n  fragment InfiniteScrollPosts_query on Query\n  @refetchable(queryName: \"InfiniteScrollPostsQuery\")\n  @argumentDefinitions(\n    first: { type: \"Int\", defaultValue: 20 }\n    after: { type: \"String\" }\n  ) {\n    posts(first: $first, after: $after)\n    @connection(key: \"InfiniteScroll_posts\") {\n      edges {\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n    }\n  }\n`;\n\nfunction InfiniteScrollPosts({ query }) {\n  const { data, loadNext, hasNext, isLoadingNext } = usePaginationFragment(\n    InfiniteScrollFragment,\n    query\n  );\n\n  const observerRef = useRef();\n  const loadMoreRef = useRef();\n\n  useEffect(() => {\n    const observer = new IntersectionObserver(\n      (entries) => {\n        if (entries[0].isIntersecting && hasNext && !isLoadingNext) {\n          loadNext(20);\n        }\n      },\n      { threshold: 0.5 }\n    );\n\n    const currentRef = loadMoreRef.current;\n    if (currentRef) {\n      observer.observe(currentRef);\n    }\n\n    observerRef.current = observer;\n\n    return () => {\n      if (currentRef) {\n        observer.unobserve(currentRef);\n      }\n    };\n  }, [hasNext, isLoadingNext, loadNext]);\n\n  return (\n    <div>\n      {data.posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n\n      {hasNext && (\n        <div ref={loadMoreRef} className=\"load-more-trigger\">\n          {isLoadingNext && <Spinner />}\n        </div>\n      )}\n\n      {!hasNext && <div>No more posts</div>}\n    </div>\n  );\n}\n```\n\n### 3. Bidirectional Pagination\n\n```javascript\n// BidirectionalPosts.jsx\nconst BidirectionalFragment = graphql`\n  fragment BidirectionalPosts_query on Query\n  @refetchable(queryName: \"BidirectionalPostsQuery\")\n  @argumentDefinitions(\n    first: { type: \"Int\" }\n    after: { type: \"String\" }\n    last: { type: \"Int\" }\n    before: { type: \"String\" }\n  ) {\n    posts(first: $first, after: $after, last: $last, before: $before)\n    @connection(key: \"Bidirectional_posts\") {\n      edges {\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n      pageInfo {\n        hasNextPage\n        hasPreviousPage\n        startCursor\n        endCursor\n      }\n    }\n  }\n`;\n\nfunction BidirectionalPosts({ query }) {\n  const {\n    data,\n    loadNext,\n    loadPrevious,\n    hasNext,\n    hasPrevious,\n    isLoadingNext,\n    isLoadingPrevious\n  } = usePaginationFragment(BidirectionalFragment, query);\n\n  return (\n    <div>\n      {hasPrevious && (\n        <button\n          onClick={() => loadPrevious(10)}\n          disabled={isLoadingPrevious}\n        >\n          {isLoadingPrevious ? ''Loading...'' : ''Load Previous''}\n        </button>\n      )}\n\n      {data.posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n\n      {hasNext && (\n        <button\n          onClick={() => loadNext(10)}\n          disabled={isLoadingNext}\n        >\n          {isLoadingNext ? ''Loading...'' : ''Load Next''}\n        </button>\n      )}\n    </div>\n  );\n}\n```\n\n### 4. Filtered Pagination\n\n```javascript\n// FilteredPosts.jsx\nconst FilteredPostsFragment = graphql`\n  fragment FilteredPosts_query on Query\n  @refetchable(queryName: \"FilteredPostsQuery\")\n  @argumentDefinitions(\n    first: { type: \"Int\", defaultValue: 10 }\n    after: { type: \"String\" }\n    status: { type: \"PostStatus\" }\n    authorId: { type: \"ID\" }\n  ) {\n    posts(\n      first: $first\n      after: $after\n      status: $status\n      authorId: $authorId\n    )\n    @connection(key: \"FilteredPosts_posts\") {\n      edges {\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n    }\n  }\n`;\n\nfunction FilteredPosts({ query }) {\n  const [status, setStatus] = useState(''PUBLISHED'');\n  const [authorId, setAuthorId] = useState(null);\n\n  const { data, loadNext, hasNext, refetch } = usePaginationFragment(\n    FilteredPostsFragment,\n    query\n  );\n\n  const handleFilterChange = (newStatus, newAuthorId) => {\n    setStatus(newStatus);\n    setAuthorId(newAuthorId);\n\n    refetch({\n      first: 10,\n      after: null,\n      status: newStatus,\n      authorId: newAuthorId\n    });\n  };\n\n  return (\n    <div>\n      <FilterControls\n        status={status}\n        authorId={authorId}\n        onChange={handleFilterChange}\n      />\n\n      {data.posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n\n      {hasNext && (\n        <button onClick={() => loadNext(10)}>Load More</button>\n      )}\n    </div>\n  );\n}\n```\n\n### 5. Pagination with Search\n\n```javascript\n// SearchablePosts.jsx\nconst SearchablePostsFragment = graphql`\n  fragment SearchablePosts_query on Query\n  @refetchable(queryName: \"SearchablePostsQuery\")\n  @argumentDefinitions(\n    first: { type: \"Int\", defaultValue: 10 }\n    after: { type: \"String\" }\n    searchTerm: { type: \"String\" }\n  ) {\n    posts(first: $first, after: $after, searchTerm: $searchTerm)\n    @connection(key: \"SearchablePosts_posts\") {\n      edges {\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n      totalCount\n    }\n  }\n`;\n\nfunction SearchablePosts({ query }) {\n  const [searchTerm, setSearchTerm] = useState('''');\n  const { data, loadNext, hasNext, refetch, isLoadingNext } =\n    usePaginationFragment(SearchablePostsFragment, query);\n\n  const handleSearch = (term) => {\n    setSearchTerm(term);\n    refetch({\n      first: 10,\n      after: null,\n      searchTerm: term\n    });\n  };\n\n  return (\n    <div>\n      <SearchInput\n        value={searchTerm}\n        onChange={handleSearch}\n        placeholder=\"Search posts...\"\n      />\n\n      <div>\n        Showing {data.posts.edges.length} of {data.posts.totalCount} posts\n      </div>\n\n      {data.posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n\n      {hasNext && (\n        <button onClick={() => loadNext(10)} disabled={isLoadingNext}>\n          {isLoadingNext ? ''Loading...'' : ''Load More''}\n        </button>\n      )}\n    </div>\n  );\n}\n```\n\n### 6. Optimistic Pagination Updates\n\n```javascript\n// OptimisticPaginationPosts.jsx\nconst CreatePostMutation = graphql`\n  mutation OptimisticPaginationCreatePostMutation(\n    $input: CreatePostInput!\n    $connections: [ID!]!\n  ) {\n    createPost(input: $input) {\n      postEdge @prependEdge(connections: $connections) {\n        cursor\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n    }\n  }\n`;\n\nfunction OptimisticPaginationPosts({ query }) {\n  const { data } = usePaginationFragment(PostsFragment, query);\n  const [commit] = useMutation(CreatePostMutation);\n\n  const connectionID = ConnectionHandler.getConnectionID(\n    ''client:root'',\n    ''Posts_posts''\n  );\n\n  const handleCreate = (title, body) => {\n    commit({\n      variables: {\n        input: { title, body },\n        connections: [connectionID]\n      },\n\n      optimisticResponse: {\n        createPost: {\n          postEdge: {\n            cursor: ''temp-cursor'',\n            node: {\n              id: `temp-${Date.now()}`,\n              title,\n              body,\n              createdAt: new Date().toISOString(),\n              author: {\n                id: currentUser.id,\n                name: currentUser.name\n              }\n            }\n          }\n        }\n      }\n    });\n  };\n\n  return (\n    <div>\n      <CreatePostForm onSubmit={handleCreate} />\n      {data.posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n    </div>\n  );\n}\n```\n\n### 7. Paginated Tabs\n\n```javascript\n// TabbedPosts.jsx\nconst TabbedPostsFragment = graphql`\n  fragment TabbedPosts_user on User\n  @refetchable(queryName: \"TabbedPostsQuery\")\n  @argumentDefinitions(\n    draftsFirst: { type: \"Int\", defaultValue: 10 }\n    draftsAfter: { type: \"String\" }\n    publishedFirst: { type: \"Int\", defaultValue: 10 }\n    publishedAfter: { type: \"String\" }\n  ) {\n    draftPosts: posts(\n      first: $draftsFirst\n      after: $draftsAfter\n      status: DRAFT\n    )\n    @connection(key: \"TabbedPosts_draftPosts\") {\n      edges {\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n    }\n\n    publishedPosts: posts(\n      first: $publishedFirst\n      after: $publishedAfter\n      status: PUBLISHED\n    )\n    @connection(key: \"TabbedPosts_publishedPosts\") {\n      edges {\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n    }\n  }\n`;\n\nfunction TabbedPosts({ user }) {\n  const [activeTab, setActiveTab] = useState(''published'');\n  const { data } = usePaginationFragment(TabbedPostsFragment, user);\n\n  const posts =\n    activeTab === ''draft'' ? data.draftPosts : data.publishedPosts;\n\n  return (\n    <div>\n      <Tabs value={activeTab} onChange={setActiveTab}>\n        <Tab value=\"published\">Published</Tab>\n        <Tab value=\"draft\">Drafts</Tab>\n      </Tabs>\n\n      {posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n    </div>\n  );\n}\n```\n\n### 8. Virtual Scrolling with Pagination\n\n```javascript\n// VirtualizedPosts.jsx\nimport { useVirtualizer } from ''@tanstack/react-virtual'';\nimport { graphql, usePaginationFragment } from ''react-relay'';\n\nconst VirtualizedPostsFragment = graphql`\n  fragment VirtualizedPosts_query on Query\n  @refetchable(queryName: \"VirtualizedPostsQuery\")\n  @argumentDefinitions(\n    first: { type: \"Int\", defaultValue: 50 }\n    after: { type: \"String\" }\n  ) {\n    posts(first: $first, after: $after)\n    @connection(key: \"VirtualizedPosts_posts\") {\n      edges {\n        node {\n          id\n          ...PostCard_post\n        }\n      }\n    }\n  }\n`;\n\nfunction VirtualizedPosts({ query }) {\n  const { data, loadNext, hasNext, isLoadingNext } = usePaginationFragment(\n    VirtualizedPostsFragment,\n    query\n  );\n\n  const parentRef = useRef();\n  const posts = data.posts.edges.map(e => e.node);\n\n  const virtualizer = useVirtualizer({\n    count: posts.length,\n    getScrollElement: () => parentRef.current,\n    estimateSize: () => 200,\n    overscan: 5\n  });\n\n  useEffect(() => {\n    const [lastItem] = [...virtualizer.getVirtualItems()].reverse();\n\n    if (!lastItem) return;\n\n    if (\n      lastItem.index >= posts.length - 1 &&\n      hasNext &&\n      !isLoadingNext\n    ) {\n      loadNext(50);\n    }\n  }, [\n    hasNext,\n    loadNext,\n    isLoadingNext,\n    posts.length,\n    virtualizer.getVirtualItems()\n  ]);\n\n  return (\n    <div ref={parentRef} style={{ height: ''600px'', overflow: ''auto'' }}>\n      <div\n        style={{\n          height: `${virtualizer.getTotalSize()}px`,\n          position: ''relative''\n        }}\n      >\n        {virtualizer.getVirtualItems().map(virtualItem => (\n          <div\n            key={virtualItem.key}\n            style={{\n              position: ''absolute'',\n              top: 0,\n              left: 0,\n              width: ''100%'',\n              transform: `translateY(${virtualItem.start}px)`\n            }}\n          >\n            <PostCard post={posts[virtualItem.index]} />\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n```\n\n### 9. Pagination State Management\n\n```javascript\n// PaginationStateManager.jsx\nfunction PaginationStateManager({ query }) {\n  const {\n    data,\n    loadNext,\n    hasNext,\n    isLoadingNext,\n    refetch\n  } = usePaginationFragment(PostsFragment, query);\n\n  const [paginationState, setPaginationState] = useState({\n    currentPage: 1,\n    itemsPerPage: 10,\n    totalLoaded: 0\n  });\n\n  const handleLoadMore = () => {\n    const itemsToLoad = paginationState.itemsPerPage;\n    loadNext(itemsToLoad);\n\n    setPaginationState(prev => ({\n      ...prev,\n      currentPage: prev.currentPage + 1,\n      totalLoaded: prev.totalLoaded + itemsToLoad\n    }));\n  };\n\n  const handleChangePageSize = (newSize) => {\n    setPaginationState(prev => ({\n      ...prev,\n      itemsPerPage: newSize\n    }));\n\n    refetch({\n      first: newSize,\n      after: null\n    });\n  };\n\n  return (\n    <div>\n      <div>\n        Page {paginationState.currentPage} -\n        Loaded {paginationState.totalLoaded} items\n      </div>\n\n      <select\n        value={paginationState.itemsPerPage}\n        onChange={(e) => handleChangePageSize(Number(e.target.value))}\n      >\n        <option value={10}>10 per page</option>\n        <option value={25}>25 per page</option>\n        <option value={50}>50 per page</option>\n      </select>\n\n      {data.posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n\n      {hasNext && (\n        <button onClick={handleLoadMore} disabled={isLoadingNext}>\n          Load More\n        </button>\n      )}\n    </div>\n  );\n}\n```\n\n### 10. Custom Pagination Hook\n\n```javascript\n// hooks/usePagination.js\nimport { useState, useCallback } from ''react'';\nimport { usePaginationFragment } from ''react-relay'';\n\nexport function usePagination(fragment, fragmentRef, options = {}) {\n  const {\n    onLoadMore,\n    onLoadPrevious,\n    onRefetch,\n    pageSize = 10\n  } = options;\n\n  const {\n    data,\n    loadNext,\n    loadPrevious,\n    hasNext,\n    hasPrevious,\n    isLoadingNext,\n    isLoadingPrevious,\n    refetch\n  } = usePaginationFragment(fragment, fragmentRef);\n\n  const [page, setPage] = useState(1);\n\n  const handleLoadNext = useCallback(() => {\n    loadNext(pageSize);\n    setPage(p => p + 1);\n    onLoadMore?.();\n  }, [loadNext, pageSize, onLoadMore]);\n\n  const handleLoadPrevious = useCallback(() => {\n    loadPrevious(pageSize);\n    setPage(p => Math.max(1, p - 1));\n    onLoadPrevious?.();\n  }, [loadPrevious, pageSize, onLoadPrevious]);\n\n  const handleRefetch = useCallback((variables) => {\n    refetch(variables);\n    setPage(1);\n    onRefetch?.();\n  }, [refetch, onRefetch]);\n\n  return {\n    data,\n    page,\n    hasNext,\n    hasPrevious,\n    isLoadingNext,\n    isLoadingPrevious,\n    loadNext: handleLoadNext,\n    loadPrevious: handleLoadPrevious,\n    refetch: handleRefetch\n  };\n}\n\n// Usage\nfunction PostsList({ query }) {\n  const {\n    data,\n    page,\n    hasNext,\n    loadNext,\n    refetch\n  } = usePagination(PostsFragment, query, {\n    pageSize: 20,\n    onLoadMore: () => console.log(''Loaded more''),\n    onRefetch: () => console.log(''Refetched'')\n  });\n\n  return (\n    <div>\n      <div>Page {page}</div>\n      <button onClick={() => refetch({ first: 20 })}>Refresh</button>\n\n      {data.posts.edges.map(({ node }) => (\n        <PostCard key={node.id} post={node} />\n      ))}\n\n      {hasNext && <button onClick={loadNext}>Load More</button>}\n    </div>\n  );\n}\n```\n\n## Best Practices\n\n1. **Use @connection directive** - Ensure proper cache updates\n2. **Implement loading states** - Show feedback during pagination\n3. **Handle edge cases** - Empty states, no more data\n4. **Optimize page size** - Balance UX and performance\n5. **Use infinite scroll wisely** - Consider virtual scrolling for large lists\n6. **Implement search/filter** - Allow users to narrow results\n7. **Cache pagination state** - Preserve scroll position\n8. **Handle errors gracefully** - Retry failed pagination requests\n9. **Test pagination thoroughly** - Edge cases, network failures\n10. **Monitor performance** - Track pagination metrics\n\n## Common Pitfalls\n\n1. **Missing @connection directive** - Cache updates fail\n2. **Incorrect cursor management** - Duplicate or missing items\n3. **No loading states** - Poor user experience\n4. **Over-fetching** - Requesting too many items per page\n5. **Memory leaks** - Not cleaning up observers\n6. **Missing error handling** - Failed requests break pagination\n7. **Inconsistent page sizes** - Confusing user experience\n8. **Not handling empty states** - Poor UX for no results\n9. **Race conditions** - Multiple concurrent pagination requests\n10. **Missing accessibility** - Keyboard navigation, screen readers\n\n## When to Use\n\n- Displaying large lists of data\n- Building infinite scroll interfaces\n- Creating feed-based applications\n- Implementing search results\n- Building e-commerce product listings\n- Creating social media timelines\n- Developing comment threads\n- Building admin dashboards\n- Creating data tables\n- Implementing file browsers\n\n## Resources\n\n- [Relay Pagination](https://relay.dev/docs/guided-tour/list-data/pagination/)\n- [Connection Specification](https://relay.dev/graphql/connections.htm)\n- [usePaginationFragment](https://relay.dev/docs/api-reference/use-pagination-fragment/)\n- [Cursor Connections](https://graphql.org/learn/pagination/)\n- [Relay Examples](https://github.com/relayjs/relay-examples)\n"},"lastSynced":"2026-03-02T02:26:24.580Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing efficient data loading and display capabilities with GraphQL and cursor-based pagination.","zh":"非常适合需要高效数据加载和显示capabilities的Frontend Agents，尤其是使用GraphQL和基于游标的分页。","ja":"フロントエンドエージェントが効率的なデータロードと表示機能を必要とする場合に最適です。特にGraphQLとカーソルベースのページネーションを使用する場合に効果的です。","ko":"프론트엔드 에이전트가 효율적인 데이터 로딩 및 표시 기능을 필요로 할 때 적합합니다. 특히 GraphQL 및 커서 기반 페이징을 사용할 때 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan capacidades de carga y visualización de datos eficientes con GraphQL y paginación basada en cursores.","fr":"Parfait pour les agents Frontend qui ont besoin de capacités de chargement et d''affichage de données efficaces avec GraphQL et une pagination basée sur les curseurs.","de":"Perfekt für Frontend-Agents, die effiziente Datenlade- und Anzeigefunktionen mit GraphQL und cursorbasierter Paginierung benötigen.","pt":"Perfeito para Agentes Frontend que precisam de capacidades de carregamento e exibição de dados eficientes com GraphQL e paginação baseada em cursor.","ru":"Идеально для фронтенд-агентов, которым необходимы эффективные возможности загрузки и отображения данных с помощью GraphQL и курсорной пагинации.","ar":"مثالي للعملاء الأماميين الذين يحتاجون إلى قدرات تحميل وعرض بيانات فعالة مع GraphQL وتنقّل الصفحات القائمة على المؤشر."},"recommendation":{"en":"Empowers agents to efficiently load and display large datasets using Relay''s cursor-based pagination with automatic cache updates and connection management through hooks like usePaginationFragment, leveraging the GraphQL Cursor Connections Specification for seamless infinite scroll and load more patterns.","zh":"赋予代理高效加载和显示大量数据的能力，使用Relay的基于游标的分页功能，自动缓存更新和连接管理，通过诸如usePaginationFragment的hook，利用GraphQL游标连接规范，实现无缝的无限滚动和加载更多模式。","ja":"エージェントに効率的なデータロードと表示機能を提供します。Relayのカーソルベースのページネーションを使用し、自動キャッシュ更新と接続管理を実現します。usePaginationFragmentなどのhookを使用し、GraphQLカーソル接続仕様を活用して、無限スクロールやロードモアパターンをシームレスに実現します。","ko":"에이전트가 효율적으로大量의 데이터를 로드하고 표시할 수 있는 기능을 제공합니다. Relay의 커서 기반 페이징을 사용하여 자동 캐시 업데이트와 연결 관리를 수행하며, usePaginationFragment와 같은 hook를 통해 GraphQL 커서 연결 규격을 활용하여 무한 스크롤 및 로드 모어 패턴을無缝하게 구현합니다.","es":"Habilita a los agentes a cargar y mostrar conjuntos de datos grandes de manera eficiente utilizando la paginación basada en cursores de Relay con actualizaciones de caché automáticas y gestión de conexiones a través de ganchos como usePaginationFragment, aprovechando la especificación de conexiones de cursor de GraphQL para patrones de desplazamiento infinito y carga de más elementos de manera fluida.","fr":"Permet aux agents de charger et d''afficher des grands ensembles de données de manière efficace en utilisant la pagination basée sur les curseurs de Relay avec des mises à jour de cache automatiques et une gestion des connexions via des crochets comme usePaginationFragment, en exploitant la spécification de connexions de curseur GraphQL pour des modèles de défilement infini et de chargement de plus de manière transparente.","de":"Ermächtigt Agenten, große Datensätze effizient zu laden und anzuzeigen, indem Relay''s cursorbasierte Paginierung mit automatischen Cache-Aktualisierungen und Verbindungsverwaltung durch Haken wie usePaginationFragment verwendet wird, wobei die GraphQL-Cursor-Connections-Spezifikation für nahtlose Endlosscroll- und Lade-Mehr-Muster genutzt wird.","pt":"Habilita os agentes a carregar e exibir conjuntos de dados grandes de forma eficiente usando a paginação baseada em cursor do Relay com atualizações de cache automáticas e gerenciamento de conexões por meio de ganchos como usePaginationFragment, aproveitando a Especificação de Conexões de Cursor GraphQL para padrões de rolagem infinita e carregar mais sem problemas.","ru":"Наделяет агентов возможностью эффективно загружать и отображать большие наборы данных, используя курсорную пагинацию Relay с автоматическими обновлениями кэша и управлением подключениями посредством крючков, таких как usePaginationFragment, используя спецификацию курсорных подключений GraphQL для бесшовной бесконечной прокрутки и загрузки дополнительных данных.","ar":"تمكّن العملاء من تحميل وعرض مجموعات بيانات كبيرة بفعالية باستخدام تنقّل الصفحات القائمة على المؤشر من Relay مع تحديثات ذاكرة التخزين المؤقت الآلية وإدارة الاتصالات من خلال مشابك مثل usePaginationFragment، مستفيدة من مواصفات اتصالات المؤشرات GraphQL لنمط لفّ افتراضي ومواصفات تحميل المزيد بدون مشاكل."},"useCases":{"en":["Implementing infinite scroll for large datasets","Optimizing data loading with automatic cache updates","Managing connections for efficient pagination"],"zh":["实现大型数据集的无限滚动","使用自动缓存更新优化数据加载","管理连接以实现高效的分页"],"ja":["大きなデータセットの無限スクロールの実装","自動キャッシュ更新を使用したデータロードの最適化","効率的なページネーションのために接続を管理"],"ko":["대형 데이터셋의 무한 스크롤 구현","자동 캐시 업데이트를 사용한 데이터 로드 최적화","효율적인 페이징을 위한 연결 관리"],"es":["Implementar desplazamiento infinito para grandes conjuntos de datos","Optimizar la carga de datos con actualizaciones de caché automáticas","Gestionar conexiones para una paginación eficiente"],"fr":["Mettre en œuvre un défilement infini pour de grands ensembles de données","Optimiser le chargement de données avec des mises à jour de cache automatiques","Gérer les connexions pour une pagination efficace"],"de":["Implementierung von Endlosscroll für große Datensätze","Optimierung der Datenladung mit automatischen Cache-Aktualisierungen","Verbindungsverwaltung für effiziente Paginierung"],"pt":["Implementar rolagem infinita para conjuntos de dados grandes","Otimizar carregamento de dados com atualizações de cache automáticas","Gerenciar conexões para paginação eficiente"],"ru":["Реализация бесконечной прокрутки для больших наборов данных","Оптимизация загрузки данных с автоматическими обновлениями кэша","Управление подключениями для эффективной пагинации"],"ar":["تنفيذ لفّ افتراضي لمجموعات بيانات كبيرة","تحسين تحميل البيانات مع تحديثات ذاكرة التخزين المؤقت الآلية","إدارة الاتصالات للتنقّل الصفحات الفعال"]},"limitations":{"en":["Requires GraphQL schema setup","Relay-specific implementation needed"],"zh":["需要设置GraphQL模式","需要Relay特定的实现"],"ja":["GraphQLスキーマの設定が必要","Relay特有の実装が必要"],"ko":["GraphQL 스키마 설정이 필요합니다","Relay 특有的 구현이 필요합니다"],"es":["Requiere configuración de esquema GraphQL","Se requiere implementación específica de Relay"],"fr":["Nécessite une configuration de schéma GraphQL","Nécessite une implémentation spécifique de Relay"],"de":["Benötigt GraphQL-Schema-Einrichtung","Benötigt Relay-spezifische Implementierung"],"pt":["Requer configuração do esquema GraphQL","Implementação específica do Relay necessária"],"ru":["Требуется настройка схемы GraphQL","Необходима реализация, специфичная для Relay"],"ar":["يتطلب إعداد مخطط GraphQL","تحتاج إلى تنفيذ محدد من Relay"]},"version":3},"contentHash":"f24f1da675d6af8b9e047207a0edd95df99bc2216e2e792ff1888876fc4f81f9","qualityScore":52}');
